postStartCommand:
docker run -d --name master_dev_preview_sidecar --restart unless-stopped -p 8383:80 -v devws_projects:/usr/share/nginx/html:ro nginx:alpine /bin/sh -c 'printf "server {
    listen 80;
    root /usr/share/nginx/html;
    autoindex on;
    autoindex_exact_size off;
    autoindex_localtime on;
    charset utf-8;
    add_header Cache-Control "no-cache, no-store, must-revalidate";
}
" > /etc/nginx/conf.d/default.conf && exec nginx -g "daemon off;"' 2>/dev/null || docker start master_dev_preview_sidecar 2>/dev/null || true
